        .instance
        .api
        .rust_arc_decrement_strong_count_AccountingSnapshotPtr,
  );
}

@sealed
class TimeTraceApiImpl extends RustOpaque implements TimeTraceApi {
  // Not to be used by end users
  TimeTraceApiImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  TimeTraceApiImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_TimeTraceApi,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_TimeTraceApi,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_TimeTraceApiPtr,
  );

  /// Add a new diary entry for a date. Returns the new entry id.
  PlatformInt64 addDiaryEntry({
    required String date,
    required String content,
  }) => RustLib.instance.api.crateApiTimeTraceApiAddDiaryEntry(
    that: this,
    date: date,
    content: content,
  );

  /// Register a diary image for a date.
  String addDiaryImage({required String date, required String path}) => RustLib
      .instance
      .api
      .crateApiTimeTraceApiAddDiaryImage(that: this, date: date, path: path);

  /// Clear ALL tracked usage data (sessions + page visits).
  void clearData() =>
      RustLib.instance.api.crateApiTimeTraceApiClearData(that: this);

  /// Delete a diary entry by id.
  void deleteDiaryEntry({required PlatformInt64 id}) => RustLib.instance.api
      .crateApiTimeTraceApiDeleteDiaryEntry(that: this, id: id);

  /// Export one canonical accounting snapshot as versioned CSV.
  ///
  /// The external String contract is preserved. Invalid input or an
  /// unavailable snapshot produces a header-only document instead of
  /// silently substituting today's date.
  String exportCsv({required String start, required String end}) => RustLib
      .instance
      .api
      .crateApiTimeTraceApiExportCsv(that: this, start: start, end: end);

  /// Run canonical export on the FRB normal worker, preserving actual errors.
  /// A legitimate partial/unknown snapshot remains successful canonical CSV;
  /// the existing producer fence and snapshot degradation policy are unchanged.
  Future<String> exportCsvAsync({required String start, required String end}) =>
      RustLib.instance.api.crateApiTimeTraceApiExportCsvAsync(
        that: this,
        start: start,
        end: end,
      );

  /// Query and map exactly one canonical accounting snapshot. Current reads
  /// first use the accepted producer fence; historical reads remain durable
  /// and side-effect free.
  Future<AccountingSnapshotDto> getAccountingSnapshot({
    required AccountingRangeRequest range,
    required AccountingAsOfRequest asOf,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetAccountingSnapshot(
    that: this,
    range: range,
    asOf: asOf,
  );

  /// Fence the producer at one Current boundary, then query exactly one
  /// canonical snapshot. A failed fence still queries at the producer-owned
  /// boundary so the core ledger returns a partial snapshot with an unknown
  /// tail after the last acknowledged watermark.
  AccountingSnapshot getAccountingSnapshotCurrent({
    required String startUtc,
    required String endUtc,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetAccountingSnapshotCurrent(
    that: this,
    startUtc: startUtc,
    endUtc: endUtc,
  );

  /// Hourly active-seconds for one app on a date (24 buckets).
  Int64List getAppHourly({required String appName, required String date}) =>
      RustLib.instance.api.crateApiTimeTraceApiGetAppHourly(
        that: this,
        appName: appName,
        date: date,
      );

  /// Extract an exe icon as raw RGBA pixels.
  IconDto? getAppIcon({required String exePath}) => RustLib.instance.api
      .crateApiTimeTraceApiGetAppIcon(that: this, exePath: exePath);

  /// Read the current user configuration.
  ConfigDto getConfig() =>
      RustLib.instance.api.crateApiTimeTraceApiGetConfig(that: this);

  /// One-call dashboard payload: usage split + overall stats.
  DashboardDataDto getDashboardData({
    required String start,
    required String end,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetDashboardData(
    that: this,
    start: start,
    end: end,
  );

  /// Full day detail: active/idle totals, session timeline, diary.
  DayDetailDto getDayDetail({required String date}) => RustLib.instance.api
      .crateApiTimeTraceApiGetDayDetail(that: this, date: date);

  /// Hourly active-seconds for a day (24 buckets) — for the heatmap.
  Int64List getDayHourly({required String date}) => RustLib.instance.api
      .crateApiTimeTraceApiGetDayHourly(that: this, date: date);

  /// The day's draft content, if any.
  String? getDiaryDraft({required String date}) => RustLib.instance.api
      .crateApiTimeTraceApiGetDiaryDraft(that: this, date: date);

  /// Get all diary entries for a month range (for calendar markers).
  List<(String, String)> getDiaryEntries({
    required String start,
    required String end,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetDiaryEntries(
    that: this,
    start: start,
    end: end,
  );

  /// All diary entries in a range with ids + status, newest first.
  List<DiaryEntryDto> getDiaryEntriesDetailed({
    required String start,
    required String end,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetDiaryEntriesDetailed(
    that: this,
    start: start,
    end: end,
  );

  /// Diary image paths in a date range (for calendar cell overlays).
  List<(String, String)> getDiaryImages({
    required String start,
    required String end,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetDiaryImages(
    that: this,
    start: start,
    end: end,
  );

  /// All diary images with their entry link: (date, entry_id, path).
  List<(String, PlatformInt64?, String)> getDiaryImagesDetailed({
    required String start,
    required String end,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetDiaryImagesDetailed(
    that: this,
    start: start,
    end: end,
  );

  /// Image paths attached to a diary entry (朋友圈 album).
  List<String> getDiaryImagesForEntry({required PlatformInt64 entryId}) =>
      RustLib.instance.api.crateApiTimeTraceApiGetDiaryImagesForEntry(
        that: this,
        entryId: entryId,
      );

  /// Apps active within a specific hour of a date (seconds per app).
  List<AppUsageDto> getHourApps({required String date, required int hour}) =>
      RustLib.instance.api.crateApiTimeTraceApiGetHourApps(
        that: this,
        date: date,
        hour: hour,
      );

  /// All startup entries.
  List<StartupDto> getStartupEntries() =>
      RustLib.instance.api.crateApiTimeTraceApiGetStartupEntries(that: this);

  /// Overall recording statistics.
  StatsDto getStats({required String start, required String end}) => RustLib
      .instance
      .api
      .crateApiTimeTraceApiGetStats(that: this, start: start, end: end);

  /// Per-app active/idle split for a date range (dates as "YYYY-MM-DD").
  List<AppUsageDto> getUsageSplit({
    required String start,
    required String end,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetUsageSplit(
    that: this,
    start: start,
    end: end,
  );

  /// Active seconds for this week (Mon→today) and last week (full).
  (PlatformInt64, PlatformInt64) getWeekTotals() =>
      RustLib.instance.api.crateApiTimeTraceApiGetWeekTotals(that: this);

  /// Page-level breakdown for an app on a date.
  List<PageDto> getWindowTitles({
    required String appName,
    required String date,
  }) => RustLib.instance.api.crateApiTimeTraceApiGetWindowTitles(
    that: this,
    appName: appName,
    date: date,
  );

  /// Reports whether a database read has entered its non-panicking fallback.
  bool isDatabaseDegraded() =>
      RustLib.instance.api.crateApiTimeTraceApiIsDatabaseDegraded(that: this);

  /// Returns whether TimeTrace is configured to start for the current user.
  bool isSelfStartEnabled() =>
      RustLib.instance.api.crateApiTimeTraceApiIsSelfStartEnabled(that: this);

  /// Whether tracking is currently paused.
  bool isTrackingPaused() =>
      RustLib.instance.api.crateApiTimeTraceApiIsTrackingPaused(that: this);

  /// Publish: promote the day's draft or insert a new published entry.
  PlatformInt64 publishDiary({required String date, required String content}) =>
      RustLib.instance.api.crateApiTimeTraceApiPublishDiary(
        that: this,
        date: date,
        content: content,
      );

  /// Remove a diary image.
  void removeDiaryImage({required String path}) => RustLib.instance.api
      .crateApiTimeTraceApiRemoveDiaryImage(that: this, path: path);

  /// Resolve a startup command line to its clean exe path (env-expanded,
  /// quotes/args stripped). Returns None if no .exe is found.
  String? resolveExePath({required String command}) => RustLib.instance.api
      .crateApiTimeTraceApiResolveExePath(that: this, command: command);

  /// Autosave a draft for a date (one draft per day). Returns its id.
  PlatformInt64 saveDiaryDraft({
    required String date,
    required String content,
  }) => RustLib.instance.api.crateApiTimeTraceApiSaveDiaryDraft(
    that: this,
    date: date,
    content: content,
  );

  /// Persist user configuration (applies on next monitor start).
  void setConfig({required ConfigDto config}) => RustLib.instance.api
      .crateApiTimeTraceApiSetConfig(that: this, config: config);

  /// Set the diary entry for a date.
  String setDiary({required String date, required String content}) => RustLib
      .instance
      .api
      .crateApiTimeTraceApiSetDiary(that: this, date: date, content: content);

  /// Link a staged diary image to a diary entry.
  void setDiaryImageEntry({
    required String path,
    required PlatformInt64 entryId,
  }) => RustLib.instance.api.crateApiTimeTraceApiSetDiaryImageEntry(
    that: this,
    path: path,
    entryId: entryId,
  );

  /// Configures current-user startup without requiring administrator rights.
  void setSelfStartEnabled({required bool enabled, required bool minimized}) =>
      RustLib.instance.api.crateApiTimeTraceApiSetSelfStartEnabled(
        that: this,
        enabled: enabled,
        minimized: minimized,
      );

  /// Pause or resume the background tracking monitor.
  void setTrackingPaused({required bool paused}) => RustLib.instance.api
      .crateApiTimeTraceApiSetTrackingPaused(that: this, paused: paused);

  /// Enable/disable a startup entry.
